import {FACTIONS,REP_RANKS,factionRank,BUILDINGS,buildingCost,SECRETS,isNight,STAT_NAMES} from '../content/living-world.js?v=0.8.0';
import {RECIPES} from '../core/living-world.js?v=0.8.0';
import {ZONES,ENEMIES,ITEM_TEMPLATES} from '../content/region.js?v=0.3.1';
import {salePrice} from '../content/economy.js?v=0.3.1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const statName=k=>STAT_NAMES[k]||k.toUpperCase();
export function sellable(h,s,item){return !Object.values(h.equipment).includes(item.id)&&salePrice(ITEM_TEMPLATES[item.template],item)>0&&!s.offers?.some(o=>o.status==='pending'&&o.item===item.id);}
export function renderLivingPanel(name,h,s,selection=new Set()){
 if(name==='world')return{title:'Світ, що пам’ятає',html:`<p class="notice">${isNight(s.clock)?'Ніч':'День'} · до зміни ${Math.ceil(300-s.clock%300)} с активної гри. Покровитель: ${FACTIONS[h.patron]?.name||'ще не обраний'}.</p><div class="reward-grid">${[['factions','Фракції та репутація','Представники чекають у південній частині Вербової слободи.'],['homestead','Власна садиба','Двір на півдні слободи: травник, майстерня, трофеї.'],['secrets','Таємниці локацій','Рунічні загадки, замурована кімната й нічний дух.'],['bestiary','Полювання','Відстежуйте істоту або бажану частину комплекту.']].map(([id,title,desc])=>`<article class="card"><h3>${title}</h3><p>${desc}</p><button class="btn" data-open="${id}">Відкрити</button></article>`).join('')}</div>`};
 if(name==='factions')return{title:'Фракції та репутація',html:`<p class="notice">Допомагати можна всім. Дев’ять завдань доступні у представників у слободі та в журналі. Покровительство — від рівня 20 і довіри 250. Перше безкоштовне, зміна — 5 відлунь. Змінюється лише активне благословення; довіра зберігається.</p><div class="card-grid">${Object.entries(FACTIONS).map(([id,f])=>{const rep=h.reputation?.[id]||0;return `<article class="card"><h3>${f.name}</h3><p>${f.desc}</p><p>${f.leader} · Вербова слобода<br>${factionRank(rep).name}: ${rep} довіри</p><p>${REP_RANKS.slice(1).map(r=>r.value+' — '+r.name).join('<br>')}</p><p>Благословення: ${f.perk}</p><button class="btn" data-patron="${id}" ${rep<250||h.level<20||h.patron===id?'disabled':''}>${h.patron===id?'Ваш покровитель':h.patron?'Змінити · 5 відлунь':'Обрати покровителя'}</button><p>Крамниця представника:</p>${[1,2,3].map(t=>`<button class="btn secondary" data-faction-buy="${id}" data-tier="${t}" ${rep<[100,250,500][t-1]||h.level<t*10?'disabled':''}>${esc(ITEM_TEMPLATES['faction-'+id+'-'+t].name)} · ${1000*t} Z</button>`).join('')}<p>Довіра 250 відкриває рецепт: ${RECIPES[id].name}.</p></article>`}).join('')}</div><button class="btn secondary" data-open="quest">Відкрити журнал завдань</button>`};
 if(name==='homestead'){const home=h.homestead||{garden:0,workshop:0,hall:0,nextHarvest:0,trophies:[]};return{title:'Садиба мандрівника',html:`<p class="notice">Особиста садиба — на півдні Вербової слободи. Будуйте й отримуйте припаси біля двору поза боєм. Початкову траву та руду можна придбати у доглядача нижче. Улюблені матеріали захищені від витрат. Установлено трофеїв: ${home.trophies.length}, бонус +${home.trophies.length*15} здоров’я.</p><div class="card-grid">${Object.entries(BUILDINGS).map(([id,b])=>{const cost=buildingCost(id,home[id]);return `<article class="card"><h3>${b.name} · ${home[id]}/3</h3><p>${b.desc}</p><button class="btn" data-home-upgrade="${id}" ${home[id]>=3?'disabled':''}>${home[id]>=3?'Завершено':`Покращити · ${cost.zeny} Z + ${cost.count} ${ITEM_TEMPLATES[cost.material].name}`}</button></article>`}).join('')}</div><h3>Припаси доглядача</h3><button class="btn secondary" data-home-supply="herb">Придбати 5 трав · 100 Z</button><button class="btn secondary" data-home-supply="ore">Придбати 5 руди · 300 Z</button><button class="btn secondary" data-open="homestead">Оновити стан садиби</button><h3>Травник</h3><p>${home.garden?'Урожай: '+home.garden*3+' трави та зілля.':'Спершу побудуйте травник.'} ${home.nextHarvest>s.clock?'Ще '+Math.ceil(home.nextHarvest-s.clock)+' с активної гри.':''}</p><button class="btn" data-home-harvest="yes" ${!home.garden||home.nextHarvest>s.clock?'disabled':''}>Зібрати врожай</button><h3>Рецепти майстерні</h3>${Object.entries(RECIPES).map(([id,r])=>`<article class="card"><h3>${r.name}</h3><p>${ITEM_TEMPLATES[r.out].name} ×${r.count} · 200 Z + ${Object.entries(r.materials).map(([k,n])=>ITEM_TEMPLATES[k].name+' ×'+Math.max(1,Math.ceil(n/Math.max(1,home.workshop)))).join(', ')}</p><button class="btn secondary" data-home-craft="${id}" ${home.workshop<1||(h.reputation?.[id]||0)<250?'disabled':''}>Виготовити</button></article>`).join('')}<h3>Зала трофеїв · ${home.trophies.length}/${home.hall}</h3>${Object.entries(ENEMIES).filter(([id,e])=>e.boss&&h.bestiary?.[id]?.kills).map(([id,e])=>`<button class="btn secondary" data-home-trophy="${id}">${home.trophies.includes(id)?'Зняти':'Виставити'}: ${e.name}</button>`).join('')||'<p>Переможіть першого боса, щоб отримати трофей для зали.</p>'}`};}
 if(name==='secrets')return{title:'Таємниці старих стежок',html:`<p class="notice">Підійдіть до каменя, прочитайте підказку й натисніть три руни у правильному порядку. Помилка починає загадку заново. Кожна нагорода видається один раз.</p><div class="card-grid">${Object.entries(SECRETS).map(([id,d])=>`<article class="card"><h3>${d.name}</h3><p>${ZONES[d.zone].name} · ${h.secrets?.[id]?'Розгадано ✓':'Рун активовано: '+(h.runeProgress?.[id]||0)+'/3'}</p><p class="dialogue">${d.hint}</p>${d.runes.map((r,n)=>`<button class="btn secondary" data-rune-id="${id}" data-rune="${n}" ${h.secrets?.[id]?'disabled':''}>${r}</button>`).join('')}</article>`).join('')}</div><h3>Прихована кімната катакомб</h3><p>Камінь у вхідній залі відчиняє північну нішу. У скрині чекає особистий Дзвін загубленої кімнати.</p><button class="btn" data-secret-claim="secret-vault" ${h.secrets?.['secret-vault']?'disabled':''}>Забрати нагороду біля скрині</button><h3>Дух нічної верби</h3><p>Шукайте біля лісового привалу вночі. ${isNight(s.clock)?'Зараз ніч.':'До ночі '+Math.ceil(300-s.clock%600)+' с активної гри.'}</p><button class="btn" data-secret-claim="night-spirit" ${h.secrets?.['night-spirit']||!isNight(s.clock)?'disabled':''}>Вислухати духа · руна та 3 відлуння</button>`};
 if(name==='bulk'){const chosen=h.inventory.filter(i=>selection.has(i.id)),total=chosen.reduce((n,i)=>n+salePrice(ITEM_TEMPLATES[i.template],i),0);return{title:'Вибір і продаж речей',html:`<p class="notice">Зірочка захищає річ від продажу, розбору й передачі. Споряджені, особисті та квестові речі продавати не можна. Виберіть до 200 предметів; усі ціни показані до підтвердження.</p><p>Вибрано ${chosen.length} · ${total} Z</p><button class="btn secondary" data-sale-clear="yes">Зняти вибір</button><details><summary>Продати вибрані речі</summary><button class="btn" data-sale-confirm="yes" ${!chosen.length?'disabled':''}>Підтвердити продаж ${chosen.length} речей · ${total} Z</button></details>${h.inventory.map(i=>`<article class="storage-row"><div><b>${esc(ITEM_TEMPLATES[i.template].name)}${i.quality?' +'+i.quality:''}</b><small>${i.favorite?'★ Улюблене':salePrice(ITEM_TEMPLATES[i.template],i)+' Z'}</small></div><button class="btn secondary" data-favorite="${i.id}" aria-pressed="${!!i.favorite}">${i.favorite?'★ Захищено':'☆ Захистити'}</button><button class="btn secondary" data-sale-select="${i.id}" aria-pressed="${selection.has(i.id)}" ${!sellable(h,s,i)?'disabled':''}>${selection.has(i.id)?'✓ Вибрано':'Вибрати'}</button></article>`).join('')}`};}
 return null;
}
